import { lazy } from 'react';
import { BarChart3 as IcBarChart3, FileText as IcFileText, Gauge as IcGauge, Sparkles as IcSparkles } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Inventory Insights — hub page for the Inventory menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 3 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'InventoryInsights'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const ServiceLevelDashboard = lazy(() => import('./ServiceLevelDashboard'));
const InventoryIntelligence = lazy(() => import('./InventoryIntelligence'));
const InventoryReport = lazy(() => import('./InventoryReport'));

export const TABS = [
  { id: 'service', label: 'Service Level', icon: IcGauge, page: 'ServiceLevelDashboard', Component: ServiceLevelDashboard },
  { id: 'intel', label: 'Inventory Intel', icon: IcSparkles, page: 'InventoryIntelligence', Component: InventoryIntelligence },
  { id: 'report', label: 'Inventory Report', icon: IcFileText, page: 'InventoryReport', Component: InventoryReport },
];

export default function InventoryInsights({ setPage }) {
  return (
    <TabHub
      icon={IcBarChart3}
      eyebrow="Inventory"
      title="Inventory Insights"
      subtitle="Service level against the promise, intelligence and the month-wise report"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
